window.__ta = () => document.querySelector('.composer textarea');
window.__type = (el, v) => { const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype; Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
window.__open = (el) => { el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, button: 0, pointerType: 'mouse' })); };
window.__alt = (code) => window.dispatchEvent(new KeyboardEvent('keydown', { key: code.slice(3).toLowerCase(), code, altKey: true, bubbles: true }));
window.__blur = () => { document.activeElement && document.activeElement.blur && document.activeElement.blur(); document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); };
window.__chat = () => { const s = window.__S(); return s.chats.find(c => c.id === s.chatId) };
window.__until = async (fn, ms) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { try { if (fn()) return Math.round((Date.now() - t0) / 1000) + 's'; } catch (e) {} await window.__sleep(100); } return 'TIMEOUT'; };
return 'tools';
